// Pure project computation: runs even when its parent canvas is closed.
export async function run({ inputs, modules, parameters }) {
  const math = modules.tensorMath;
  await math.ready;
  return [...new Set([...parameters.corpus])].sort((a,b) => a.codePointAt(0)-b.codePointAt(0));
}

// Pure project computation: runs even when its parent canvas is closed.
export async function run({ inputs, modules, parameters }) {
  const math = modules.tensorMath;
  await math.ready;
  if (typeof inputs.text !== 'string') throw new Error('Connect a text prompt.');
  const chars = [...inputs.text].slice(-parameters.blockSize);
  if (!chars.length) throw new Error('Enter a nonempty prompt.');
  const ids = chars.map(char => inputs.vocabulary.indexOf(char));
  if (ids.some(id => id < 0)) throw new Error('Prompt contains a character outside the corpus vocabulary. Edit the vocabulary corpus.');
  return ids;
}

async function run() {
  // state.result: the complete input value; it is shared with render().
  state.result = inputs.input1 ?? inputs['in-0'] ?? null;
  await render();
}

data.render:
function render({ state, renderer }) {
  // state.result is the input value; tune these defaults or use Properties.
  const fontSize = renderer?.fontSize ?? 26;
  const precision = renderer?.precision ?? 4;
  const slice = renderer?.slice ?? 0;
  return <MathValue value={state.result} fontSize={fontSize} precision={precision} slice={slice}/>;
}

